<script lang="ts">
  import { onDestroy } from 'svelte';
  import {
    setEvolutionModalShow,
    setEvolutionModalClose,
    setEvolutionModalCanDismiss,
    runEvolutionModalOnComplete,
    type EvolutionModalPayload,
  } from '../bridge/evolutionModalBridge.js';

  type Phase = 'idle' | 'what' | 'glow' | 'flash' | 'congrats' | 'fusion';

  const WHAT_MS = 1400;
  const GLOW_MS = 2200;
  const FLASH_MS = 350;

  let visible = $state(false);
  let payload = $state<EvolutionModalPayload | null>(null);
  let phase = $state<Phase>('idle');
  let timers: ReturnType<typeof setTimeout>[] = [];

  const spriteUrl = $derived.by(() => {
    if (!payload) return '';
    if (phase === 'what' || phase === 'glow') return payload.oldSpriteUrl;
    return payload.newSpriteUrl;
  });

  const spriteAlt = $derived.by(() => {
    if (!payload) return '';
    if (phase === 'what' || phase === 'glow') return payload.oldDisplayName;
    return payload.newDisplayName;
  });

  const dialogText = $derived.by(() => {
    if (!payload) return '';
    if (phase === 'what' || phase === 'glow') return payload.whatText;
    if (phase === 'congrats') return payload.congratsText;
    return '';
  });

  const showContinue = $derived(phase === 'congrats' || phase === 'fusion');

  function clearTimers() {
    timers.forEach((t) => clearTimeout(t));
    timers = [];
  }

  function schedule(ms: number, fn: () => void) {
    timers.push(setTimeout(fn, ms));
  }

  function openModalShell() {
    const modal = document.getElementById('evolutionModal');
    if (modal) modal.classList.add('show');
  }

  function closeModalShell() {
    const modal = document.getElementById('evolutionModal');
    if (modal) modal.classList.remove('show');
  }

  function startCinematicSequence(data: EvolutionModalPayload) {
    clearTimers();
    if (data.reducedMotion) {
      phase = 'congrats';
      return;
    }
    phase = 'what';
    schedule(WHAT_MS, () => {
      phase = 'glow';
      schedule(GLOW_MS, () => {
        phase = 'flash';
        schedule(FLASH_MS, () => {
          phase = 'congrats';
        });
      });
    });
  }

  function show(data: EvolutionModalPayload) {
    clearTimers();
    payload = data;
    visible = true;
    openModalShell();

    if (data.mode === 'fusion-short') {
      phase = 'fusion';
      return;
    }

    startCinematicSequence(data);
  }

  function dismiss() {
    const wasCinematic = payload?.mode === 'cinematic';
    const hadCongrats = phase === 'congrats';
    clearTimers();
    visible = false;
    payload = null;
    phase = 'idle';
    closeModalShell();

    if (wasCinematic && hadCongrats) {
      runEvolutionModalOnComplete();
    }
  }

  function close() {
    dismiss();
  }

  function canDismissNow(): boolean {
    return phase === 'congrats' || phase === 'fusion';
  }

  setEvolutionModalShow(show);
  setEvolutionModalClose(close);
  setEvolutionModalCanDismiss(canDismissNow);

  onDestroy(() => {
    clearTimers();
    setEvolutionModalShow(() => {});
    setEvolutionModalClose(() => {});
    setEvolutionModalCanDismiss(() => true);
  });
</script>

{#if visible && payload}
  <div
    id="evolutionModalContent"
    class="evolution-scene"
    class:evolution-scene--flash={phase === 'flash'}
    class:evolution-scene--reduced={payload.reducedMotion}
    data-action="stopPropagation"
    data-action-stop
  >
    {#if payload.mode === 'fusion-short'}
      <div class="evolution-sprite-slot evolution-sprite-slot--fusion">
        <img src={payload.oldSpriteUrl} alt={payload.oldDisplayName} class="evolution-sprite evolution-sprite--small" />
        <span class="evolution-fusion-arrow" aria-hidden="true">→</span>
        <img src={payload.newSpriteUrl} alt={payload.newDisplayName} class="evolution-sprite evolution-sprite--small" />
      </div>
      <div class="evolution-dialog-box">
        <p class="evolution-dialog-text evolution-dialog-text--title">{payload.fusionTitle}</p>
        <p class="evolution-dialog-text">{payload.fusionBody}</p>
        <button type="button" class="evolution-continue" onclick={() => dismiss()}>
          {payload.confirmLabel}
        </button>
      </div>
    {:else}
      <div class="evolution-sprite-slot">
        {#if spriteUrl}
          <img
            src={spriteUrl}
            alt={spriteAlt}
            class="evolution-sprite"
            class:evolution-sprite--glow={phase === 'glow'}
            class:evolution-sprite--reveal={phase === 'flash' || phase === 'congrats'}
          />
        {/if}
      </div>
      <div class="evolution-dialog-box" class:evolution-dialog-box--hidden={phase === 'flash'}>
        {#if dialogText}
          <p class="evolution-dialog-text">{dialogText}</p>
        {/if}
        {#if showContinue}
          <button type="button" class="evolution-continue" onclick={() => dismiss()}>
            {payload.confirmLabel}
          </button>
        {/if}
      </div>
    {/if}
  </div>
{/if}
